<script setup>
import { computed, onMounted, ref } from 'vue'
import { AlertTriangle, BadgeCheck, CloudOff, Play, RefreshCw, RotateCcw, ShieldCheck } from '@lucide/vue'
import { createIntegrationFaultDrill, executeIntegrationFaultStep, getIntegrationFaultDrills } from '../api/integrationFaultDrill'

const workspace=ref({organizations:[],selected:null,truthfulness:null}),loading=ref(true),action=ref(''),error=ref(''),notice=ref('')
const selected=computed(()=>workspace.value.selected),latest=computed(()=>selected.value?.runs?.[0]||null)
function detail(value){return typeof value==='string'?value:value?.message||value?.code||'操作失败'}
async function load(){loading.value=true;error.value='';try{workspace.value=await getIntegrationFaultDrills()}catch(e){error.value=detail(e.detail||e.message)}finally{loading.value=false}}
async function run(key,command,message){action.value=key;error.value='';notice.value='';try{await command();notice.value=message;await load()}catch(e){error.value=detail(e.detail||e.message)}finally{action.value=''}}
async function create(){await run('create',()=>createIntegrationFaultDrill({organization_id:selected.value.organization_id,run_key:`fc4-fault-drill-${Date.now()}` }),'七场景故障演练已建立')}
async function next(){const scenario=latest.value.scenario_plan[latest.value.current_scenario];await run('next',()=>executeIntegrationFaultStep(latest.value.id,{expected_lock_version:latest.value.lock_version}),`${scenario.label} 已执行并完成恢复校验`)}
const done=computed(()=>latest.value?.status==='passed'||latest.value?.status==='failed')
onMounted(load)
</script>
<template><main class="drill-page"><header><div><p class="eyebrow"><RotateCcw :size="14"/> FC4 resilience verification</p><h1>集成故障演练</h1><p>逐步执行重复、乱序、撤销、冲突、断连、超时和死信，验证恢复后仍可继续处理。</p></div><button class="icon" aria-label="刷新故障演练" @click="load"><RefreshCw :size="17"/></button></header>
<p v-if="error" class="notice error"><AlertTriangle :size="15"/>{{error}}</p><p v-if="notice" class="notice ok"><BadgeCheck :size="15"/>{{notice}}</p><p v-if="loading" class="notice"><RefreshCw class="spin" :size="15"/>正在恢复演练状态</p>
<section v-if="!loading&&workspace.truthfulness" class="boundary"><CloudOff :size="18"/><div><strong>{{workspace.truthfulness.data_label}}</strong><span>{{workspace.truthfulness.disclaimer}}</span></div></section>
<section v-if="!loading&&!selected" class="empty"><ShieldCheck :size="36"/><h2>尚无可管理的演示组织</h2><RouterLink class="primary" to="/enterprise-training">前往企业培训</RouterLink></section>
<template v-else-if="!loading"><section class="control"><div><span>演练范围</span><strong>7 类故障 · 串行执行</strong></div><div><span>真实网络</span><strong>不使用</strong></div><div><span>权威数据策略</span><strong>前后哈希必须一致</strong></div><button v-if="!latest||done" class="primary" :disabled="Boolean(action)" @click="create">新建演练</button><button v-else class="primary" :disabled="Boolean(action)" @click="next"><Play :size="14"/>执行下一场景</button></section>
<section v-if="!latest" class="empty small"><RotateCcw :size="30"/><h2>尚未建立故障演练</h2><p>创建后七类场景按固定顺序执行，每一步都生成不可变证据。</p></section>
<template v-else><section class="authority" :class="latest.authority_before_hash===latest.authority_after_hash?'safe':'changed'"><ShieldCheck :size="18"/><div><strong>{{latest.authority_before_hash===latest.authority_after_hash?'内部权威数据未改变':'权威数据校验失败'}}</strong><code>{{latest.authority_before_hash.slice(0,18)}}... → {{latest.authority_after_hash.slice(0,18)}}...</code></div><span>{{latest.status}}</span></section>
<section class="scenario-grid"><article v-for="(scenario,index) in latest.scenario_plan" :key="scenario.key" :class="{complete:index<latest.current_scenario,current:index===latest.current_scenario&&!done}"><div class="number">{{index+1}}</div><div><span>{{scenario.key}}</span><strong>{{scenario.label}}</strong><small>{{scenario.fault_code}}</small></div><BadgeCheck v-if="index<latest.current_scenario" :size="17"/></article></section>
<section class="steps"><div class="heading"><div><h2>不可变演练证据</h2><p>故障状态、恢复动作和权威哈希均由服务端生成。</p></div><span>{{latest.steps.length}} / 7</span></div><div v-if="!latest.steps.length" class="inline-empty">执行首个场景后显示证据。</div><article v-for="step in latest.steps" :key="step.id"><div><span>{{step.scenario_index}} · {{step.scenario_key}}</span><strong>{{step.fault_code}}</strong><code>{{step.evidence_hash.slice(0,18)}}...</code></div><div><small>故障结果</small><code>{{JSON.stringify(step.after_snapshot)}}</code></div><div><small>恢复结果</small><code>{{JSON.stringify(step.recovery_snapshot)}}</code></div><strong class="pass">{{step.outcome}}</strong></article></section></template></template></main></template>
<style scoped>.drill-page{max-width:1320px;margin:auto;color:#20272a;padding:4px 2px 42px}.drill-page header{display:flex;justify-content:space-between;align-items:flex-start;padding:24px 2px 20px;border-bottom:1px solid #dce2e5}.drill-page h1{font-size:24px;margin:6px 0}.drill-page header p:last-child{font-size:13px;color:#667177}.eyebrow{display:flex;gap:7px;align-items:center;font-size:10px;font-weight:750;color:#1f6370;text-transform:uppercase}.icon{width:36px;height:36px;display:grid;place-items:center;border:1px solid #d8dfe2;background:#fff;border-radius:7px}.notice{display:flex;align-items:center;gap:7px;padding:11px 14px;background:#f4f7f8;font-size:10px}.notice.error{background:#fff1ef;color:#963f35}.notice.ok{background:#eef8f1;color:#276046}.boundary{display:flex;align-items:center;gap:10px;padding:12px 15px;background:#fff8e6;color:#65511f;border-bottom:1px solid #e4d7ad}.boundary div{display:flex;flex-wrap:wrap;gap:5px 14px}.boundary strong{font-size:11px}.boundary span{font-size:10px}.control{display:grid;grid-template-columns:1fr 1fr 1.3fr auto;align-items:center;background:#f6f9fa;border-bottom:1px solid #dce2e5}.control>div{padding:14px 18px;border-right:1px solid #e1e6e8}.control span{display:block;font-size:8px;color:#77858a}.control strong{font-size:11px}.control button{margin:0 14px}.primary{display:inline-flex;align-items:center;justify-content:center;gap:6px;border:0;border-radius:6px;padding:9px 12px;background:#245f69;color:#fff;font-size:10px;font-weight:650;text-decoration:none}.authority{display:flex;align-items:center;gap:10px;padding:15px;margin-top:20px;border:1px solid #bdd3c5;background:#f1f8f3;color:#285e43}.authority.changed{border-color:#e3b8b0;background:#fff1ef;color:#963f35}.authority div{display:flex;flex-direction:column}.authority strong{font-size:11px}.authority code{font-size:8px}.authority>span{margin-left:auto;font-size:9px;text-transform:uppercase}.scenario-grid{display:grid;grid-template-columns:repeat(7,1fr);margin:16px 0;border:1px solid #dce2e5}.scenario-grid article{min-width:0;display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:8px;padding:12px;border-right:1px solid #e2e8ea;opacity:.55}.scenario-grid article:last-child{border:0}.scenario-grid article.complete{opacity:1;background:#f1f8f3;color:#285e43}.scenario-grid article.current{opacity:1;background:#eef5f6;color:#245f69}.number{width:22px;height:22px;display:grid;place-items:center;border:1px solid currentColor;border-radius:50%;font-size:9px}.scenario-grid article>div:nth-child(2){display:flex;min-width:0;flex-direction:column}.scenario-grid span,.scenario-grid small{font-size:7px;overflow-wrap:anywhere}.scenario-grid strong{font-size:9px}.steps{padding-top:14px}.heading{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:12px}.heading h2{font-size:15px}.heading p{font-size:9px;color:#748087}.heading>span{font-size:9px}.steps>article{display:grid;grid-template-columns:1fr 1.2fr 1.2fr auto;align-items:center;gap:12px;padding:12px;border:1px solid #dce2e5;border-bottom:0}.steps>article:last-child{border-bottom:1px solid #dce2e5}.steps>article>div{display:flex;min-width:0;flex-direction:column}.steps span,.steps small{font-size:8px;color:#748087}.steps strong{font-size:9px}.steps code{font-size:7px;overflow-wrap:anywhere}.pass{color:#276046;text-transform:uppercase}.inline-empty,.empty{color:#748087;font-size:10px;text-align:center}.inline-empty{padding:25px;border:1px dashed #d1dadd}.empty{min-height:360px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:9px}.empty.small{min-height:260px}.empty h2{font-size:15px;color:#20272a}.spin{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:900px){.control{grid-template-columns:1fr 1fr}.control button{margin:12px}.scenario-grid{grid-template-columns:1fr}.scenario-grid article{border-right:0;border-bottom:1px solid #e2e8ea}.steps>article{grid-template-columns:1fr}.authority{align-items:flex-start}.authority>span{margin-left:0}}@media(max-width:500px){.control{grid-template-columns:1fr}.control>div{border-right:0;border-bottom:1px solid #e1e6e8}.control button{width:calc(100% - 28px)}.boundary{align-items:flex-start}.drill-page h1{font-size:21px}}
</style>
